def rows4(logs):
    """-> (ci, j, present, g_src) over the logs of one rollout; tolerant of a log with no c_src column (the label form need not log a closing input)"""
    cols = {k: [] for k in ("ci", "j", "present", "g_src")}
    for z in logs:
        for k in cols:
            cols[k].append(np.asarray(z[k]))
    return (np.concatenate(cols["ci"]).astype(np.int64), np.concatenate(cols["j"]).astype(np.int64), np.concatenate(cols["present"]).astype(bool),
            np.concatenate(cols["g_src"]).astype(np.float64))


def pl_check(rows, JL):
    """control e7, planted-join runs. rows = (ci, j, present, g_src) of one rollout; JL = {lead_valid, lead_gap, off, n} of JLE.npz. A logged step (ci, j) maps to the join row off[ci] + j (ci indexes the clip
    order of the join: an open definition, see PRESATTR_READ_DEFS.md). On every logged step with a lead the gap the rule received equals lead_gap of that row within 1e-3 m; the logged steps with a lead are the
    logged steps whose join row is valid by the rule's own test for a join (marking 1, gap finite, 0 <= gap <= 60 m)."""
    ci, j, pres, g = rows
    off, n = np.asarray(JL["off"]).astype(np.int64), np.asarray(JL["n"]).astype(np.int64)
    lv, lg = np.asarray(JL["lead_valid"]), np.asarray(JL["lead_gap"], dtype=np.float64)
    ok_map = (ci >= 0) & (ci < len(n))
    ok_map[ok_map] = (j[ok_map] >= 0) & (j[ok_map] < n[ci[ok_map]])
    row = np.zeros(len(ci), np.int64)
    row[ok_map] = off[ci[ok_map]] + j[ok_map]
    gj = np.where(ok_map, lg[row], np.nan)
    valid = ok_map & (lv[row] == 1) & np.isfinite(gj) & (gj >= 0.0) & (gj <= GAP_MAX_M)
    n_unmapped = int((~ok_map).sum())
    n_extra = int((pres & ~valid).sum())                 # a lead in the log where the join gives none
    n_miss = int((~pres & valid).sum())                  # no lead in the log where the join gives one
    both = pres & valid
    n_gap_bad = int((np.abs(g[both] - gj[both]) > TOL_PL).sum()) if both.any() else 0
    n_gap_nan = int((~np.isfinite(g[both])).sum()) if both.any() else 0
    n_lead = int(pres.sum())
    bad = []
    if n_lead == 0:
        bad.append("no logged step with a lead")
    if n_unmapped:
        bad.append("%d logged steps map to no row of the join (clip index or frame out of range)" % n_unmapped)
    if n_extra or n_miss:
        bad.append("%d of %d logged steps disagree on the lead: %d with a lead in the log that the planted join does not give (marking, finiteness or 0 to 60 m), %d with no lead in the log where it gives one"
                   % (n_extra + n_miss, len(ci), n_extra, n_miss))
    if n_gap_bad or n_gap_nan:
        bad.append("%d lead steps whose logged gap differs from the lead_gap of the planted join by more than %g m (%d not finite)" % (n_gap_bad + n_gap_nan, TOL_PL, n_gap_nan))
    return {"PASS": not bad, "failures": bad, "n_rows": int(len(ci)), "n_lead_rows": n_lead, "n_join_valid_rows": int(valid.sum()), "n_unmapped": n_unmapped, "n_lead_not_in_join": n_extra,
            "n_join_lead_not_in_log": n_miss, "n_gap_bad": n_gap_bad, "share_of_rule_steps_with_a_lead": (n_lead / len(ci)) if len(ci) else None}


