def load_pres_file(p):
    """-> {p, has_out, off, n} of a presence file of pres_dump.py (plain numpy load)"""
    with np.load(p, allow_pickle=False) as z:
        return {"p": np.asarray(z["p"], np.float64), "has_out": np.asarray(z["has_out"], bool), "off": np.asarray(z["off"], np.int64), "n": np.asarray(z["n"], np.int64)}


def pres_at(F, ci, fr):
    """-> (pf [B] float64, NaN where there is no usable value, have [B] bool): the file's row off[ci] + fr when the clip index is inside the file, the frame is in 0..n[ci]-1, has_out is true and p is finite"""
    ci, fr = np.asarray(ci, np.int64), np.asarray(fr, np.int64)
    nc = len(F["off"])
    inside = (ci >= 0) & (ci < nc)
    cc = np.where(inside, ci, 0)
    inside = inside & (fr >= 0) & (fr < F["n"][cc])
    row = np.where(inside, F["off"][cc] + fr, 0)
    inside = inside & (row < len(F["p"]))
    row = np.where(inside, row, 0)
    have = inside & F["has_out"][row] & np.isfinite(F["p"][row])
    return np.where(have, F["p"][row], np.nan), have


def load_logs_sides(pull, run, m, S):
    """-> (logs, sides): the rule logs of a run at setting S (the first log; the mid log when the setting has a rule every n steps, else only if it lies on disk) and the side file of each
    (`<log minus .npz>_rd.npz`), each side file required"""
    d = os.path.join(pull, "I10%s_s%d" % (run, m), "ticks")
    names = ["rule_log_I10%s_s%d.npz" % (run, m), "rule_log_mid_I10%s_s%d.npz" % (run, m)]
    logs, sides = [], []
    for i, nm in enumerate(names):
        p = os.path.join(d, nm)
        if not os.path.isfile(p):
            if i == 0 or SPEC[S]["every"] is not None:
                raise SystemExit("REFUSED: no rule log %s" % p)
            continue
        sp = p[:-4] + "_rd.npz"
        if not os.path.isfile(sp):
            raise SystemExit("REFUSED: no side file %s" % sp)
        for lst, q in ((logs, p), (sides, sp)):
            with np.load(q, allow_pickle=False) as z:
                lst.append({k: z[k] for k in z.files})
    return logs, sides


LOG_NEED = ("ci", "j", "present", "src_bad", "p_src")
SIDE_NEED = ("p", "p_used", "ok")


def _eq_nan(x, y, tol):
    x, y = np.asarray(x, np.float64), np.asarray(y, np.float64)
    with np.errstate(invalid="ignore"):
        return (np.isnan(x) & np.isnan(y)) | (np.abs(x - y) <= tol)


def pres_rows_check(logs, sides, F, counts_rec):
    """control q8 (a), (b), (c) and (e) on the rows of one new run. logs and sides: lists of dicts (the log and its side file, row for row); F the presence file of the run's model seed;
    counts_rec the parsed `vis_pres_counts` of the run record (or None). The rows are the rows of all logs in order. -> dict(failures, rows, with_file, no_file, raised, lowered, raised_mask)"""
    bad = []
    if not logs or len(logs) != len(sides):
        return {"failures": ["%d rule logs and %d side files" % (len(logs or []), len(sides or []))], "raised_mask": None}
    cols = {k: [] for k in LOG_NEED + SIDE_NEED}
    for i, (z, sd) in enumerate(zip(logs, sides)):
        miss = [k for k in LOG_NEED if k not in z] + ["side " + k for k in SIDE_NEED if k not in sd]
        if miss:
            bad.append("log %d lacks %s" % (i, miss))
            continue
        n1 = len(np.asarray(z["ci"]))
        lens = {k: len(np.asarray(sd[k])) for k in SIDE_NEED}
        lens.update({k: len(np.asarray(z[k])) for k in LOG_NEED})
        if len(set(lens.values())) != 1:
            bad.append("log %d: the log and its side file have different numbers of rows %s" % (i, sorted(lens.items())))
            continue
        for k in LOG_NEED:
            cols[k].append(np.asarray(z[k]))
        for k in SIDE_NEED:
            cols[k].append(np.asarray(sd[k]))
    if bad:
        return {"failures": bad, "raised_mask": None}
    c = {k: np.concatenate(v) for k, v in cols.items()}
    ci, j = c["ci"].astype(np.int64), c["j"].astype(np.int64)
    p, pu = c["p"].astype(np.float64), c["p_used"].astype(np.float64)
    ok, sb, pres = c["ok"].astype(bool), c["src_bad"].astype(bool), c["present"].astype(bool)
    pf, have = pres_at(F, ci, j)
    with np.errstate(invalid="ignore"):
        want = np.where(have, np.fmax(p, pf), p)
        n_a = int((~_eq_nan(pu, want, TOL_P)).sum())
        n_b = int((pres != ((pu >= PRES_P_MIN) & ok & ~sb)).sum())
        n_c = int((~_eq_nan(c["p_src"], pu, TOL_P)).sum())
        raised_m = (p < PRES_P_MIN) & (pu >= PRES_P_MIN)
        lowered_m = (p >= PRES_P_MIN) & (pu < PRES_P_MIN)
    rows, with_file = int(len(ci)), int(have.sum())
    got = {"rows": rows, "with_file": with_file, "no_file": rows - with_file, "raised": int(raised_m.sum()), "lowered": int(lowered_m.sum())}
    if n_a:
        bad.append("q8 (a): %d of %d rows with p_used not equal to the larger of p and the presence file's value (p where the file has none) within %g" % (n_a, rows, TOL_P))
    if n_b:
        bad.append("q8 (b): %d of %d rows with present not equal to (p_used >= 0.5) and ok and not src_bad" % (n_b, rows))
    if n_c:
        bad.append("q8 (c): %d of %d rows with p_src not equal to p_used within %g" % (n_c, rows, TOL_P))
    if not isinstance(counts_rec, dict):
        bad.append("q8 (e): the rule log meta carries no readable vis_pres_counts")
    else:
        for k, v in got.items():
            if counts_rec.get(k) != v:
                bad.append("q8 (e): vis_pres_counts %s is %s, recomputed from the rows %s" % (k, counts_rec.get(k), v))
    if got["lowered"] or (isinstance(counts_rec, dict) and counts_rec.get("lowered")):
        bad.append("q8 (e): lowered rows: recomputed %d, record %s (none allowed)" % (got["lowered"], (counts_rec or {}).get("lowered")))
    out = dict(got)
    out["failures"] = bad
    out["raised_mask"] = raised_m
    return out


def rule_checks(a):
    """-> per-rollout dict (key S_arm_s<m>) of control q8 for the eight new rollouts: (a), (b), (c), (e) on the rows against the presence file of the run's model seed (pres_rows_check), and (d) the model reader's
    w2_one against the run's own gap file (the base file for PO, the A90 file for POA) with the rule log meta naming that file's hash and the closing switch. Rows that the presence input raised, where the gap
    file has no output and the reference run RR has no lead row, have nothing to be compared with: they are left out of (d) and counted (n_raised_rows_without_reference)."""
    per = {}
    for S, arm in new_pairs():
        gf = gap_file_of(a, arm)
        for m in SEEDS:
            key = "%s_%s_s%d" % (S, arm, m)
            try:
                if not gf or not os.path.isfile(gf):
                    per[key] = {"PASS": False, "failures": ["no gap file %s" % gf]}
                    continue
                if not os.path.isfile(pres_path(a, m)):
                    per[key] = {"PASS": False, "failures": ["no presence file %s" % pres_path(a, m)]}
                    continue
                gref = MD.gapfile_ref(gf)
                fsha = sha_file(gf)
                logs, sides = load_logs_sides(a.pull, run_name(S, arm), m, S)
                ref_logs = load_logs_setting(a.pull, run_name(S, "RR"), m, S)
                v0 = MD.lead_multi(MD.rows_of(ref_logs))
                meta = MD.meta_of(logs[0])
                try:
                    rec = json.loads(str(scalar_of(logs[0], "vis_pres_counts")))
                except (ValueError, TypeError):
                    rec = None
                pc = pres_rows_check(logs, sides, load_pres_file(pres_path(a, m)), rec)
                rows = MD.rows_of(logs)
                raised = pc.pop("raised_mask")
                keep = np.ones(len(rows[0]), bool)
                if raised is not None and len(raised) == len(keep):
                    for i in np.flatnonzero(raised):
                        k2 = (int(rows[0][i]), int(rows[1][i]))
                        if gref.get(k2) is None and k2 not in v0:
                            keep[i] = False
                r = MD.w2_one(tuple(x[keep] for x in rows), gref, v0, meta_expect={"vis_closing": 1}, meta=meta)
                ms = str(meta.get("vis_gap_file_sha256") or "").lower()
                fails = ["q8 (d): " + x for x in r.get("failures", [])]
                if not (len(ms) >= 16 and (fsha.startswith(ms) or ms.startswith(fsha))):
                    fails.append("q8 (d): rule log meta names the gap file hash %s, the gap file on disk has %s" % (ms[:16] or None, fsha[:16]))
                fails += list(pc.get("failures", []))
                r["failures"] = fails
                r["PASS"] = not fails
                r.update({k: pc.get(k) for k in ("rows", "with_file", "no_file", "raised", "lowered")})
                r["n_raised_rows_without_reference"] = int((~keep).sum())
                per[key] = r
            except (SystemExit, OSError, ValueError, KeyError) as ex:
                per[key] = {"PASS": False, "failures": ["cannot read the rollout, its reference, its side files, its presence file or its gap file: %s: %s" % (type(ex).__name__, ex)]}
    return per


def _hash_match(x, y):
    x, y = str(x or "").lower(), str(y or "").lower()
    return len(x) >= 16 and len(y) >= 16 and (x.startswith(y) or y.startswith(x))


def ctl_e0(wp_sha, rec, check_p_text, wsha, check_text, hashes_text, check_files_present, run_shas):
    """e0 wrapper (q0): the generator record of the study wrapper passes, the wrapper file on disk has the sha256 that begins b2a1d5f7242c3700 and equals the record's variant hash, the record's source hash
    begins 28bc31f21ecb4ccb, and the static check ends with `ZZ CHECK-WRAPPER-P PASS`; as the source's wrapper control, for the unchanged wrapper: its file has the hash 28bc31f21ecb4ccb, the banked check
    files are in place, the pod check ends with `ZZ CHECK-WRAPPER-V PASS` and its hashes name the wrapper; the run text of each of the eight new runs and of the identity run names a wrapper hash that begins
    with the study wrapper's."""
    bad = []
    rec = rec if isinstance(rec, dict) else {}
    if not wp_sha or not str(wp_sha).lower().startswith(WRAPPER_P_SHA):
        bad.append("the study wrapper file has sha256 %s, not %s" % ((wp_sha or "none")[:16], WRAPPER_P_SHA))
    if rec.get("pass") is not True:
        bad.append("the generator record of the study wrapper has pass %s" % rec.get("pass"))
    vs = str(rec.get("variant_sha256") or "").lower()
    if not vs.startswith(WRAPPER_P_SHA):
        bad.append("the record's variant hash is %s, not %s" % (vs[:16] or None, WRAPPER_P_SHA))
    if wp_sha and vs and str(wp_sha).lower() != vs:
        bad.append("the study wrapper file has sha256 %s, the record holds %s" % (str(wp_sha)[:16], vs[:16]))
    if not str(rec.get("source_sha256") or "").lower().startswith(WRAPPER_P_SRC):
        bad.append("the record's source hash is %s, not %s" % (str(rec.get("source_sha256") or "none")[:16], WRAPPER_P_SRC))
    if last_line(check_p_text).strip() != CHECK_P_LAST:
        bad.append("the last line of the static check of the study wrapper is %r" % last_line(check_p_text).strip())
    if wsha != WRAPPER_SHA:
        bad.append("the unchanged wrapper file is %s, not %s" % (wsha, WRAPPER_SHA))
    if not check_files_present:
        bad.append("a banked check file of the unchanged wrapper is missing")
    if last_line(check_text).strip() != CHECK_LAST:
        bad.append("the last line of the pod check of the unchanged wrapper is %r" % last_line(check_text).strip())
    if WRAPPER_SHA not in (hashes_text or ""):
        bad.append("the pod check hashes do not name %s" % WRAPPER_SHA)
    for k in new_keys() + [IDP_KEY]:
        v = run_shas.get(k)
        if v is None:
            bad.append("%s: the run text names no wrapper hash" % k)
        elif not v.startswith(WRAPPER_P_SHA):
            bad.append("%s: the run text names the wrapper hash %s, not the study wrapper's %s" % (k, v[:16], WRAPPER_P_SHA))
    return {"pass": not bad, "failures": bad, "values": {"wrapper_p_sha16": (wp_sha or "")[:16], "wrapper_sha16": wsha}}


def dump_dir(pull, nm, mm):
    return os.path.join(run_folder(pull, nm, mm), "dump_I10%s_s%d_m10_causal_heads" % (nm, mm))


def dump_names(pull, nm, mm):
    dd = dump_dir(pull, nm, mm)
    return sorted(f for f in (os.listdir(dd) if os.path.isdir(dd) else []) if f.startswith("ep") and f.endswith(".npz"))


def compare_arrays(x, y, logs=False):
    """x, y {key: array}: the differences of two npz files (list of texts). Equal means the same keys, and for every key the same dtype, shape and values (NaN equal to NaN). With logs=True the arrays of
    string or object dtype and any key named `meta` are left out of the value comparison (text and run-record keys); the key names are still compared."""
    out = []
    if sorted(x) != sorted(y):
        out.append("keys differ: only in the new file %s, only in the reference %s" % (sorted(set(x) - set(y)), sorted(set(y) - set(x))))
    for k in sorted(set(x) & set(y)):
        a_, b_ = np.asarray(x[k]), np.asarray(y[k])
        if logs and (k in META_KEYS or a_.dtype.kind in "OUS" or b_.dtype.kind in "OUS"):
            if k not in META_KEYS and (a_.dtype.kind in "OUS") != (b_.dtype.kind in "OUS"):
                out.append("%s: text in one file, numbers in the other" % k)
            continue
        if a_.shape != b_.shape or a_.dtype != b_.dtype:
            out.append("%s: shape/dtype %s %s against %s %s" % (k, a_.shape, a_.dtype, b_.shape, b_.dtype))
            continue
        eq = np.array_equal(a_, b_, equal_nan=True) if a_.dtype.kind in "fc" else np.array_equal(a_, b_)
        if not eq:
            out.append("%s: values differ" % k)
    return out


def identity_read(a):
    """control q1 inputs: the identity run IDP (CONV, model seed 0) against the banked candidate run GEc_s0. -> (failures, values): the same set of dump file names (141), every array of every dump file equal,
    the rule log arrays equal (the logs of both runs, in order; arrays of string or object dtype and any key named meta left out), the side file of IDP without a column p_used"""
    bad, vals = [], {}
    expect = int(getattr(a, "expect_dumps", EXPECT_DUMPS))
    try:
        na, nb = dump_names(a.pull, IDP_RUN, IDP_SEED), dump_names(a.pull, IDP_BASE, IDP_SEED)
        vals.update({"dump_files_identity_run": len(na), "dump_files_banked_run": len(nb)})
        if na != nb:
            bad.append("the dump file names differ: only in the identity run %s, only in the banked run %s" % (sorted(set(na) - set(nb))[:5], sorted(set(nb) - set(na))[:5]))
        if len(na) != expect:
            bad.append("the identity run has %d dump files, %d expected" % (len(na), expect))
        n_diff = 0
        for nm in sorted(set(na) & set(nb)):
            with np.load(os.path.join(dump_dir(a.pull, IDP_RUN, IDP_SEED), nm), allow_pickle=False) as za, np.load(os.path.join(dump_dir(a.pull, IDP_BASE, IDP_SEED), nm), allow_pickle=False) as zb:
                d = compare_arrays({k: za[k] for k in za.files}, {k: zb[k] for k in zb.files})
            if d:
                n_diff += 1
                if n_diff <= 10:
                    bad += ["dump %s: %s" % (nm, x) for x in d[:3]]
        vals["dump_files_with_a_difference"] = n_diff
        if n_diff > 10:
            bad.append("%d dump files differ in all (the first 10 are listed)" % n_diff)
        la, sa = load_logs_sides(a.pull, IDP_RUN, IDP_SEED, "CONV")
        lb = load_logs_setting(a.pull, IDP_BASE, IDP_SEED, "CONV")
        if len(la) != len(lb):
            bad.append("the identity run has %d rule logs, the banked run %d" % (len(la), len(lb)))
        for i, (x, y) in enumerate(zip(la, lb)):
            bad += ["rule log %d: %s" % (i, d) for d in compare_arrays(x, y, logs=True)]
        for i, sd in enumerate(sa):
            if "p_used" in sd:
                bad.append("the side file %d of the identity run has a column p_used" % i)
        vals["rule_logs_compared"] = len(la)
    except (SystemExit, OSError, ValueError, KeyError) as ex:
        bad.append("cannot read the identity run or the banked run: %s: %s" % (type(ex).__name__, ex))
    return bad, vals


def ctl_e1(bad, vals):
    """e1 identity run (q1): see identity_read"""
    return {"pass": not bad, "failures": list(bad), "values": dict(vals)}


def pres_info(a):
    """control q2 inputs. -> (files {m: {sha, meta}}, runs {key: {line, meta_sha, meta_mode}}): the presence file and pres_meta.json of head seed m; the parsed first line and the rule log meta of each new run"""
    files = {}
    for m in SEEDS:
        p = pres_path(a, m)
        files[m] = {"sha": sha_file(p) if os.path.isfile(p) else None, "meta": read_json(pres_meta_path(a, m))}
    runs = {}
    for S, arm in new_pairs():
        for m in SEEDS:
            key = "%s_%s_s%d" % (S, arm, m)
            ms = mm = None
            try:
                logs = load_logs_setting(a.pull, run_name(S, arm), m, S)
                ms, mm = scalar_of(logs[0], "vis_pres_file_sha256"), scalar_of(logs[0], "vis_pres_mode")
            except (SystemExit, OSError, ValueError, KeyError):
                pass
            runs[key] = {"line": parse_run_line(read_text(run_text_path(a.pull, run_name(S, arm), m))), "meta_sha": ms, "meta_mode": mm}
    return files, runs


def ctl_e2(files, runs):
    """e2 presence files (q2): each presence file has the sha256 that its pres_meta.json names (dump_sha256; seed equal to the head seed); the first line of each new run of model seed k names ` vis pres sha256 <the hash of
    the file of head seed k>` and ` vis-pres-mode or`, and its rule log meta names the same hash and mode"""
    bad = []
    for m in SEEDS:
        f = (files or {}).get(m) or {}
        meta = f.get("meta") if isinstance(f.get("meta"), dict) else None
        if not f.get("sha"):
            bad.append("head seed %d: no presence file" % m)
            continue
        if meta is None:
            bad.append("head seed %d: no readable pres_meta.json" % m)
            continue
        if str(f["sha"]).lower() != str(meta.get("dump_sha256") or "").lower():
            bad.append("head seed %d: the presence file has sha256 %s, pres_meta.json names %s" % (m, str(f["sha"])[:16], str(meta.get("dump_sha256") or "none")[:16]))
        try:
            sd = int(meta.get("seed"))
        except (TypeError, ValueError):
            sd = None
        if sd != m:
            bad.append("head seed %d: pres_meta.json names the seed %s" % (m, meta.get("seed")))
    if sorted(runs or {}) != sorted(new_keys()):
        bad.append("runs read: %s, expected %s" % (sorted(runs or {}), sorted(new_keys())))
    for k, r in sorted((runs or {}).items()):
        m = int(k.rsplit("_s", 1)[1])
        want = ((files or {}).get(m) or {}).get("sha")
        line = r.get("line") or {}
        for lab, got in (("the first line", line.get("pres_sha")), ("the rule log meta", r.get("meta_sha"))):
            if not got:
                bad.append("%s: %s names no presence file hash" % (k, lab))
            elif not want or not _hash_match(got, want):
                bad.append("%s: %s names the presence file %s, the file of head seed %d has %s" % (k, lab, str(got)[:16], m, str(want or "none")[:16]))
        for lab, got in (("the first line", line.get("pres_mode")), ("the rule log meta", r.get("meta_mode"))):
            if str(got) != PRES_MODE:
                bad.append("%s: %s names the presence mode %s, not %s" % (k, lab, got, PRES_MODE))
    return {"pass": not bad, "failures": bad, "values": {"presence_file_sha16": {str(m): str(((files or {}).get(m) or {}).get("sha") or "")[:16] for m in SEEDS}}}


def ref_arm(S, arm):
    """the reference run of a new run: the banked run with the same gap file at its setting (GEc for PO, A90 for POA)"""
    return {"PO": "GEc", "POA": "A90"}[arm]


def ctl_e3(lines, rc):
    """e3 arguments (q3): lines {key: (new text, reference text)} for the six new runs; the clause of note N1 per run (d2_line_failures) and the rule log shows the rule acting on steps with a lead (a share above 0).
    The q-map file of each new run being the one of its reference run is read by the lead from the printed commands of the dry run and logged before the queue start: it is not coded here."""
    bad = []
    if sorted(lines) != sorted(new_keys()):
        bad.append("run lines read: %s, expected %s" % (sorted(lines), sorted(new_keys())))
    for k, (tn, tr) in sorted(lines.items()):
        if not first_line(tn):
            bad.append("%s: no run log of the new run" % k)
            continue
        if not first_line(tr):
            bad.append("%s: no run log of the reference run" % k)
            continue
        bad += ["%s: %s" % (k, x) for x in d2_line_failures(parse_run_line(tn), parse_run_line(tr))]
        sh = (rc.get(k) or {}).get("share_of_rule_steps_with_a_lead")
        if not (sh is not None and sh > 0):
            bad.append("%s: the rule log shows no rule step with a lead (share %s)" % (k, sh))
    return {"pass": not bad, "failures": bad}


def ctl_e4(levels):
    """e4 identity of levels (q4): the reader reproduces within 1e-4 the banked levels (C, U, F) at CONV and at K0 of GEc, A90, PL, RLc, RR; read by the same code path as the new cells. levels {S: {arm: {C,U,F}}}"""
    bad = []
    for S, arms in EXPECTED.items():
        for arm, want in arms.items():
            for c, v in zip("CUF", want):
                got = (((levels or {}).get(S) or {}).get(arm) or {}).get(c)
                if got is None or not np.isfinite(got) or abs(float(got) - v) > LEVEL_TOL + 1e-12:
                    bad.append("%s %s %s: %s, expected %.4f within %g" % (S, arm, c, got, v, LEVEL_TOL))
    return {"pass": not bad, "failures": bad}


def _pytest_ok(text, nm):
    bad = []
    hits = re.findall(r"(\d+) passed", text or "")
    if not (hits and int(hits[-1]) > 0):
        bad.append("%s: no line with a count of passed tests above 0" % nm)
    if re.search(r"\b\d+ (failed|errors?)\b", text or ""):
        bad.append("%s: the test output has a failed or error count" % nm)
    return bad


def ctl_e5(text_queue, text_read, mtime_queue, mtime_read, queue_start, controls_start):
    """e5 tests (q5): the output of the queue kit's test (written by the lead outside the kit folders) and that of this kit's test each carry `N passed` and no failed or error count; the first is not later than the first
    start epoch of the queue, the second not later than the start of the controls stage"""
    bad = _pytest_ok(text_queue, "queue kit") + _pytest_ok(text_read, "reader kit")
    mq, mr, qs, cs = to_epoch(mtime_queue), to_epoch(mtime_read), to_epoch(queue_start), to_epoch(controls_start)
    if mq is None or mr is None or qs is None or cs is None:
        bad.append("a time is missing (queue test %s, reader test %s, queue start %s, controls start %s)" % (mtime_queue, mtime_read, queue_start, controls_start))
    else:
        if not mq <= qs:
            bad.append("the queue kit's test output (%s) is later than the first start epoch of the queue (%s)" % (mq, qs))
        if not mr <= cs:
            bad.append("the reader kit's test output (%s) is later than the start of the controls stage (%s)" % (mr, cs))
    return {"pass": not bad, "failures": bad}


def ctl_e6(per_setting):
    """e6 engine (q6): for each of the two settings the engine's own controls of the grid read and of the strategic grid pass (as control g8 of the model reader)"""
    bad, det = [], {}
    if sorted(per_setting) != sorted(SETTINGS):
        bad.append("settings read: %s, expected %s" % (sorted(per_setting), sorted(SETTINGS)))
    for S, v in sorted(per_setting.items()):
        r = MD.ctl_g8(v.get("grid_all_pass"), v.get("strategic_a"), v.get("strategic_b"))
        det[S] = {"grid_all_pass": v.get("grid_all_pass"), "strategic_stage_A_pass": v.get("strategic_a"), "strategic_stage_B_pass": v.get("strategic_b")}
        if not r["PASS"]:
            bad.append("%s: grid_all_pass %s, strategic stage A %s, stage B %s%s" % (S, v.get("grid_all_pass"), v.get("strategic_a"), v.get("strategic_b"),
                                                                                    (" (" + v["strategic_reason"] + ")") if v.get("strategic_reason") else ""))
    return {"pass": not bad, "failures": bad, "per_setting": det}


def ctl_e7(done, n_dumps, expect, done_marker_text=None):
    """e7 counts (q7): every new run and the identity run has its done marker and 141 dump files (`expect`). done {key: bool}, n_dumps {key: int}"""
    bad = []
    for k in new_keys() + [IDP_KEY]:
        if done.get(k) is not True:
            bad.append("%s: no T1_DONE" % k)
        if n_dumps.get(k) != expect:
            bad.append("%s: %s dump files, %s expected" % (k, n_dumps.get(k), expect))
    if done_marker_text is not None and not DONE_RE.match(last_line(done_marker_text).strip()):
        bad.append("the queue done marker reads %r" % last_line(done_marker_text)[:100])
    return {"pass": not bad, "failures": bad, "values": {"dump_files": n_dumps, "expected": expect}}


def ctl_e8(per):
    """e8 rule logs (q8): each new run, row for row (see rule_checks and pres_rows_check)"""
    bad = []
    if sorted(per) != sorted(new_keys()):
        bad.append("rollouts read: %s, expected %s" % (sorted(per), sorted(new_keys())))
    for k, v in sorted(per.items()):
        bad += ["%s: %s" % (k, x) for x in v.get("failures", [])]
        if v.get("PASS") is not True and not v.get("failures"):
            bad.append("%s: not pass" % k)
    shares = {k: {"share_of_rule_steps_with_a_lead": v.get("share_of_rule_steps_with_a_lead"), "n_rows": v.get("n_rows"), "n_lead_rows": v.get("n_lead_rows"),
                  "raised": v.get("raised"), "rows": v.get("rows"), "with_file": v.get("with_file"), "lowered": v.get("lowered"),
                  "n_raised_rows_without_reference": v.get("n_raised_rows_without_reference"),
                  "share_of_lead_steps_with_nonzero_closing": v.get("share_of_lead_steps_with_nonzero_closing")} for k, v in per.items()}
    return {"pass": not bad and bool(per), "failures": bad, "values": {"rollout_shares": shares}}


def compute_controls(a, m, wsha):
    """the nine controls from the files on disk and the engine measures `m` ({"settings": {S: {levels, grid_all_pass, strategic_a, strategic_b}}})"""
    c = {}
    wp = a.wrapper_p_file
    wp_sha = sha_file(wp) if wp and os.path.isfile(wp) else None
    present = bool(a.wrapper_check and os.path.isfile(a.wrapper_check) and a.wrapper_hashes and os.path.isfile(a.wrapper_hashes))
    shas = {"%s_%s_s%d" % (S, arm, mm): MD.run_file_sha(a.pull, run_name(S, arm), mm) for S, arm in new_pairs() for mm in SEEDS}
    shas[IDP_KEY] = MD.run_file_sha(a.pull, IDP_RUN, IDP_SEED)
    c["e0"] = ctl_e0(wp_sha, read_json(a.wrapper_p_record), read_text(a.wrapper_p_check), wsha, read_text(a.wrapper_check), read_text(a.wrapper_hashes), present, shas)
    c["e1"] = ctl_e1(*identity_read(a))
    rc = rule_checks(a)
    c["e2"] = ctl_e2(*pres_info(a))
    lines = {"%s_%s_s%d" % (S, arm, mm): (read_text(run_text_path(a.pull, run_name(S, arm), mm)), read_text(run_text_path(a.pull, run_name(S, ref_arm(S, arm)), mm)))
             for S, arm in new_pairs() for mm in SEEDS}
    c["e3"] = ctl_e3(lines, rc)
    c["e4"] = ctl_e4({S: (v or {}).get("levels") for S, v in (m.get("settings") or {}).items()})
    c["e5"] = ctl_e5(read_text(a.tests_queue), read_text(a.tests_read), a.tests_mtime_queue, a.tests_mtime_read, a.queue_start, a.controls_start)
    c["e6"] = ctl_e6(m.get("settings") or {})
    done, n_dumps = {}, {}
    for S, arm in new_pairs():
        for mm in SEEDS:
            k = "%s_%s_s%d" % (S, arm, mm)
            nm = run_name(S, arm)
            done[k] = os.path.isfile(os.path.join(run_folder(a.pull, nm, mm), "T1_DONE"))
            n_dumps[k] = len(dump_names(a.pull, nm, mm))
    done[IDP_KEY] = os.path.isfile(os.path.join(run_folder(a.pull, IDP_RUN, IDP_SEED), "T1_DONE"))
    n_dumps[IDP_KEY] = len(dump_names(a.pull, IDP_RUN, IDP_SEED))
    c["e7"] = ctl_e7(done, n_dumps, int(getattr(a, "expect_dumps", EXPECT_DUMPS)), read_text(a.done_marker) if getattr(a, "done_marker", "") else None)
    c["e8"] = ctl_e8(rc)
    return c


def assemble_controls(controls, payload, inputs):
    ok = sorted(controls) == sorted(CONTROLS) and all(isinstance(v, dict) and v.get("pass") is True for v in controls.values())
    vals = {k: v["values"] for k, v in controls.items() if isinstance(v, dict) and "values" in v}
    flat = {k: ({kk: vv for kk, vv in v.items() if kk != "values"} if isinstance(v, dict) else v) for k, v in controls.items()}
    pl = dict(payload)
    pl["control_values"] = vals
    res = {"card": CARD, "tier": TIER, "controls": flat, "all_pass": ok, "inputs": inputs}
    res["payload" if ok else "withheld"] = pl
    return res


# ============================================================================================ names (two separate derivations)
def _sg(iv):
    return -1 if iv[1] < 0.0 else (1 if iv[0] > 0.0 else 0)


def reaches(payload, S):
    """card section 4: POA lowers the unsafe rate against GEc (interval below 0) and its pooled unsafe rate is at most that of the label form plus CLOSE_TOL"""
    d = payload["settings"][S]
    return bool(d["pairs"]["POA-VS-GEc"]["U"]["interval"][1] < 0.0 and d["levels"]["POA"]["U"] <= d["levels"]["RLc"]["U"] + CLOSE_TOL)


def names_of(payload):
    """card section 4, written from the interval ends"""
    out = {}
    for S in SETTINGS:
        d = payload["settings"][S]
        pr = d["pairs"]
        p = "%s-%s-" % (PRE, S)
        for mk, mw in MEASURES:
            iv = pr["PO-VS-GEc"][mk]["interval"]
            if iv[1] < 0.0:
                out["%s_PO_%s" % (S, mw)] = p + "PRESENCE-LOWERS-" + mw
            elif iv[0] > 0.0:
                out["%s_PO_%s" % (S, mw)] = p + "PRESENCE-RAISES-" + mw
            else:
                out["%s_PO_%s" % (S, mw)] = p + "PRESENCE-" + mw + "-NOT-SEPARATED"
            iv = pr["POA-VS-GEc"][mk]["interval"]
            if iv[1] < 0.0:
                out["%s_POA_%s" % (S, mw)] = p + "BOTH-LEVERS-LOWER-" + mw
            elif iv[0] > 0.0:
                out["%s_POA_%s" % (S, mw)] = p + "BOTH-LEVERS-RAISE-" + mw
            else:
                out["%s_POA_%s" % (S, mw)] = p + "BOTH-LEVERS-" + mw + "-NOT-SEPARATED"
        iv = pr["POA-VS-RLc"]["U"]["interval"]
        out["%s_POA_LABEL" % S] = p + "BOTH-LEVERS-" + ("UNSAFE-ABOVE-LABEL-FORM" if iv[0] > 0.0 else ("UNSAFE-BELOW-LABEL-FORM" if iv[1] < 0.0 else "UNSAFE-AT-LABEL-FORM"))
        if not reaches(payload, S):
            out[S + "_OVERALL"] = p + "BOTH-LEVERS-DO-NOT-REACH-LABEL-FORM"
        elif pr["POA-VS-RLc"]["F"]["interval"][0] > 0.0:
            out[S + "_OVERALL"] = p + "BOTH-LEVERS-REACH-LABEL-FORM-AT-A-PRICE"
        else:
            out[S + "_OVERALL"] = p + "BOTH-LEVERS-REACH-LABEL-FORM-AT-NO-SEPARATED-PRICE"
    return out


def derive_all(payload):
    """independent second derivation of every name from the signs of the intervals (written apart from names_of)"""
    out = {}
    pw = {-1: "PRESENCE-LOWERS-%s", 1: "PRESENCE-RAISES-%s", 0: "PRESENCE-%s-NOT-SEPARATED"}
    bw = {-1: "BOTH-LEVERS-LOWER-%s", 1: "BOTH-LEVERS-RAISE-%s", 0: "BOTH-LEVERS-%s-NOT-SEPARATED"}
    lab = {1: "UNSAFE-ABOVE-LABEL-FORM", -1: "UNSAFE-BELOW-LABEL-FORM", 0: "UNSAFE-AT-LABEL-FORM"}
    for S in ("CONV", "K0"):
        d = payload["settings"][S]
        pre = "PRESROLL10K-" + S + "-"
        for mk, mw in (("U", "UNSAFE"), ("C", "CONTACT"), ("F", "FALLING-BEHIND")):
            out["%s_PO_%s" % (S, mw)] = pre + (pw[_sg(d["pairs"]["PO-VS-GEc"][mk]["interval"])] % mw)
            out["%s_POA_%s" % (S, mw)] = pre + (bw[_sg(d["pairs"]["POA-VS-GEc"][mk]["interval"])] % mw)
        out["%s_POA_LABEL" % S] = pre + "BOTH-LEVERS-" + lab[_sg(d["pairs"]["POA-VS-RLc"]["U"]["interval"])]
        lowers = _sg(d["pairs"]["POA-VS-GEc"]["U"]["interval"]) == -1
        near = d["levels"]["POA"]["U"] <= d["levels"]["RLc"]["U"] + 0.0045                  # the same arithmetic as reaches(), so that the two routines cannot part at the bound
        pays = _sg(d["pairs"]["POA-VS-RLc"]["F"]["interval"]) == 1
        out[S + "_OVERALL"] = pre + ("BOTH-LEVERS-DO-NOT-REACH-LABEL-FORM" if not (lowers and near) else ("BOTH-LEVERS-REACH-LABEL-FORM-AT-A-PRICE" if pays else "BOTH-LEVERS-REACH-LABEL-FORM-AT-NO-SEPARATED-PRICE"))
    return out


def all_names(payload):
    got = names_of(payload)
    exp = derive_all(payload)
    diff = ["%s: got %s, expected %s" % (k, got.get(k), v) for k, v in sorted(exp.items()) if got.get(k) != v]
    diff += ["%s: name present that the card does not have" % k for k in sorted(got) if k not in exp]
    if diff:
        raise SystemExit("REFUSED: the names are not the ones the intervals give: %s" % diff)
    return got


def flat_names(names):
    return [names[k] for k in sorted(names)]


# ============================================================================================ the pod part (grid read and strategic read per setting)
def register_runs(S):
    spec = SPEC[S]
    for arm, r in spec["runs"].items():
        R.ALL_RUNS.setdefault(r, ("RLc" if arm in ("RLc", "PL") else "RR", spec["readout"], spec["P"], "deadreckon", spec["grid"], "plan", spec["every"], 0.2))
    R.ALL_RUNS.setdefault(SPREAD, ("R0", "pinned", 0, "deadreckon", "full", "plan", None, 0.2))


def measure_setting(a, E, S, keys, ctx_cache, log):
    """grid read of the five runs of one setting (levels, pairs with intervals, families) and the strategic grid at T1-kin. Engine calls as in the model reader."""
    H = E[0]
    spec = SPEC[S]
    runs = spec["runs"]
    register_runs(S)
    pairs_def = {nm: (runs[x], runs[y]) for nm, (x, y) in PAIRS.items()}
    G = R.read_grid(a, E, spec["grid"], keys, [SPREAD] + sorted(set(runs.values())), SPREAD, pairs_def, {}, log)
    ok_levels = all(r in (G.get("levels") or {}) for r in runs.values())
    out = {"grid_all_pass": G["controls"].get("ALL_PASS") is True, "counts": G.get("counts") or {}, "levels": {}, "levels_per_seed": {}, "pairs": {}, "families": {}, "strategic": {"pairs": {}},
           "strategic_a": False, "strategic_b": False}
    if out["counts"]:
        out["instrument_bar_met"] = bool(out["counts"].get("n_lead_windows", 0) >= H.MIN_WINDOWS and out["counts"].get("n_episodes_with_lead", 0) >= H.MIN_EPISODES)
    if ok_levels:
        out["levels"] = {arm: {c: float(np.mean(G["levels"][r][c])) for c in ("C", "U", "F")} for arm, r in runs.items()}
        out["levels_per_seed"] = {arm: {c: [float(v) for v in np.asarray(G["levels"][r][c]).reshape(-1)[:2]] for c in ("C", "U", "F")} for arm, r in runs.items()}
    if G.get("pairs"):
        out["pairs"] = {nm: R.ucf(p["headway"]) for nm, p in G["pairs"].items()}
        out["families"] = {nm: {f_: R.reading(R.cells_of(p["family"]), f_) for f_ in R.NAMED} for nm, p in G["pairs"].items()}
    p_of = {"R0": 0}
    p_of.update({r: spec["P"] for r in runs.values()})
    try:
        SR, cells_s, eid_s, SS = R.strategic_grid(a, keys, sorted(p_of), p_of, log, ctx_cache)
    except SystemExit as ex:
        out["strategic_reason"] = "SystemExit: %s" % str(ex)[:200]
        return out
    except Exception as ex:                                                                   # noqa: BLE001
        out["strategic_reason"] = "%s: %s" % (type(ex).__name__, str(ex)[:200])
        return out
    sa, sb = bool(SR.get("stage_A_pass")), bool(SR.get("stage_B_pass"))
    out["strategic_a"], out["strategic_b"] = sa, sb
    out["strategic"]["controls"] = dict({k: v for k, v in SR["controls"].items() if k != "s3"}, s3=SR["controls"]["s3"].get("pass"))
    if sa and sb:
        for nm, (x, y) in STRAT_PAIRS.items():
            pr = SS.pair_read(cells_s, runs[x], runs[y], eid_s, ticks=(2,))
            pos = pr["tick2"]["pos"]
            out["strategic"]["pairs"][nm] = {"A": runs[x], "B": runs[y], "pos_30_50_80m_tick_t0_plus_20": [
                {"arc_m": arc, "mean": b["mean"], "lo": b["lo"], "hi": b["hi"], "verdict": b["verdict"], "n_per_seed": b.get("n_per_seed")} for arc, b in zip(SS.ARCS, pos)],
                "reading": R.family_of([c["verdict"] for c in pos])}
    else:
        out["strategic_reason"] = "the engine's strategic controls did not pass"
    return out


def grid_path(a, S):
    gf = SPEC[S]["grid_file"]
    return a.grid_pinned if gf == "pinned" else os.path.join(a.grid_dir, gf)


def measure(a, E, log):
    H = E[0]
    J = H.load_join()
    names_ = [str(c) for c in J["clip"]]
    ctx_cache = {}
    res = {}
    for S in SETTINGS:                                                                         # the same code path for the new cells and for the banked cells read as identity
        g = R.jl(grid_path(a, S))
        if g is None:
            res[S] = {"grid_all_pass": False, "levels": {}, "pairs": {}, "strategic_a": False, "strategic_b": False, "strategic_reason": "grid file %s cannot be read" % grid_path(a, S)}
            continue
        keys = R.grid_keys(g, names_)
        res[S] = measure_setting(a, E, S, keys, ctx_cache, log)
    return {"settings": res}


def run_controls(a):
    elog = a.out + ".engine.log"
    if os.path.exists(elog):
        raise SystemExit("REFUSED: %s exists" % elog)
    with io.open(elog, "w", encoding="utf-8", newline="\n") as fh, contextlib.redirect_stdout(fh):
        E = R.engine(a)
        m = measure(a, E, lambda s: print(s, flush=True))
    wsha = sha_file(a.wrapper_file)[:16] if a.wrapper_file and os.path.isfile(a.wrapper_file) else None
    controls = compute_controls(a, m, wsha)
    payload = {"settings": m["settings"], "family_note": FAM_NOTE}
    inputs = {"model_reader": MODEL_PATH and sha_file(MODEL_PATH), "this_reader": sha_file(os.path.abspath(__file__)), "wrapper_file_sha16": wsha,
              "gap_file_sha256": sha_file(a.gap_file) if os.path.isfile(a.gap_file) else None,
              "gap_file_a90_sha256": sha_file(margin_file(a, "A90")) if os.path.isfile(margin_file(a, "A90")) else None,
              "wrapper_p_file_sha256": sha_file(a.wrapper_p_file) if a.wrapper_p_file and os.path.isfile(a.wrapper_p_file) else None,
              "pres_files_sha256": {str(mm): (sha_file(pres_path(a, mm)) if os.path.isfile(pres_path(a, mm)) else None) for mm in SEEDS}}
    return assemble_controls(controls, payload, inputs)


def fmt_pair(p):
    return "; ".join("%s %s" % (label, json.dumps(p[mk], sort_keys=True, default=str)) for mk, label in MEASURES)


def print_sections(payload, names):
    L = ["TIER " + TIER]
    L += flat_names(names)
    for S in SETTINGS:
        d = payload["settings"][S]
        cn = d.get("counts") or {}
        L.append("setting %s (%s; grid %s): windows %s, windows with a lead %s, episodes with a lead %s, instrument bar of 200 windows and 20 episodes met %s" % (
            S, preroll_text(SPEC[S]["P"]), SPEC[S]["grid"], cn.get("n_windows"), cn.get("n_lead_windows"), cn.get("n_episodes_with_lead"), d.get("instrument_bar_met")))
        for arm in ARMS:
            lv = d["levels"][arm]
            L.append("level %s %s pooled C %.4f U %.4f F %.4f (windows with a lead %s); per model seed %s" % (S, arm, lv["C"], lv["U"], lv["F"], cn.get("n_lead_windows"),
                                                                                                          json.dumps(d["levels_per_seed"].get(arm), sort_keys=True)))
        for nm in PAIRS:
            L.append("%s %s: %s" % (S, nm, fmt_pair(d["pairs"][nm])))
        for nm in PAIRS:
            st = (d.get("strategic") or {}).get("pairs", {}).get(nm)
            L.append("families %s %s: %s strategic %s" % (S, nm, json.dumps((d.get("families") or {}).get(nm) or {}, sort_keys=True),
                                                           st["reading"] if st else "not read (%s)" % d.get("strategic_reason", "no reason recorded")))
    cv = payload.get("control_values") or {}
    e8 = cv.get("e8") or {}
    sh = e8.get("rollout_shares") or {}
    for k in sorted(sh):
        L.append("rollout %s: %s" % (k, json.dumps(sh[k], sort_keys=True)))
    return L


# ============================================================================================ synthetic world for the selftest and the tests
def _write_run(pull, name, m, first, ci, fr, present, gaps, clos=None, sha=None, done=True, ndump=3, meta=True):
    d = os.path.join(pull, "I10%s_s%d" % (name, m))
    os.makedirs(os.path.join(d, "ticks"), exist_ok=True)
    h = len(ci) // 2
    for nm, sl in (("rule_log_I10%s_s%d.npz", slice(0, h)), ("rule_log_mid_I10%s_s%d.npz", slice(h, len(ci)))):
        z = dict(ci=ci[sl], j=fr[sl], present=present[sl], g_src=gaps[sl].copy())
        if clos is not None:
            z["c_src"] = clos[sl]
        if meta:
            z.update(vis_gap_file_sha256=np.array(sha or "none"), vis_closing=np.array(1))
        np.savez(os.path.join(d, "ticks", nm % (name, m)), **z)
    io.open(os.path.join(d, "ticks", "run_I10%s_s%d.txt" % (name, m)), "w", encoding="utf-8", newline="\n").write(first + "\nrc 0 finished x\n")
    if done:
        io.open(os.path.join(d, "T1_DONE"), "w").write("")
    dd = os.path.join(d, "dump_I10%s_s%d_m10_causal_heads" % (name, m))
    os.makedirs(dd, exist_ok=True)
    for i in range(ndump):
        np.savez(os.path.join(dd, "ep%03d.npz" % i), x=np.zeros(1))


def run_line(arm_name, S, m, wrap, form, ref, tail=""):
    """a first line of a run log in the format of the queue (ref True: the banked reference lines of K0 carry no pre-roll, exec, nav or grid field)"""
    sp = SPEC[S]
    ln = "arm I10%s_s%d form %s replan steps 10 rule every %s readout causal_g kappa 0.2" % (arm_name, m, form, sp["every"])
    if not (ref and S == "K0"):
        ln += " preroll %d exec plan nav deadreckon grid %s" % (sp["P"], {"K0": PINNED_GRID_NAME, "K30": "grid_p30.json"}[S])
    ln += " model seed %d reader seed %d ckpt sha256 %s wrapper sha256 %s started 2026-11-22T10:57:07Z%s" % (m, m, ("%02x" % (m + 1)) * 32, wrap, tail)
    return ln


def make_world(base, fault=None):
    """a tiny world (3 clips of 12 frames) in which every control passes (fault None), or exactly the one control named by `fault` fails. -> (a, m, wsha)"""
    base = str(base)
    os.makedirs(base, exist_ok=True)
    pull, gd = os.path.join(base, "pull"), os.path.join(base, "grids")
    for d_ in (pull, gd):
        os.makedirs(d_, exist_ok=True)
    nk = 12
    ci, fr = np.repeat(np.arange(3), nk), np.tile(np.arange(nk), 3)
    n = len(ci)
    clips = np.array(["c0", "c1", "c2"])
    # the evaluation join and the planted join (rows in the layout row = off[ci] + j)
    lv = np.where((fr == 2) | (fr == 3), 0, 1).astype(np.int8)
    lg_eval = (10.0 + fr + 0.5 * ci).astype(np.float32)
    lg_eval[12 + 5] = 40.0                                                             # clip 1 frame 5: a label gap below 60 m, the planted gap below is above 60 m
    lg_jle = lg_eval.copy()
    lg_jle[0] = 21.0
    lg_jle[1] = 22.5
    lg_jle[12 + 5] = 75.0                                                              # camera gap above 60 m on a label row: no lead for the rule
    lg_jle[24 + 7] = np.nan                                                            # a label row with a non-finite gap in the planted join
    ej, jp = os.path.join(base, "join_eval141.npz"), os.path.join(base, "JLE.npz")
    common = dict(clip=clips, off=np.array([0, 12, 24]), n=np.array([12, 12, 12]), lead_valid=lv)
    np.savez(ej, lead_gap=lg_eval, **common)
    np.savez(jp, lead_gap=lg_jle, **common)
    # the base gap file and the LA gap file
    has = np.ones(n, bool)
    has[[2, 14, 30]] = False
    gp = os.path.join(base, "VGAPLE.npz")
    np.savez(gp, clip_index=ci, frame=fr, gap=np.where(has, 15.0 + 0.9 * fr + 0.3 * ci, np.nan), has_out=has, clips=clips, seed=np.int64(-1))
    hasla = np.ones(n, bool)
    hasla[[4, 16, 28]] = False
    lap = os.path.join(base, "VGAPA_LA.npz")
    la_gap = 20.0 + 0.5 * fr + 0.1 * ci
    np.savez(lap, clip_index=ci, frame=fr, gap=np.where(hasla, la_gap, np.nan), has_out=hasla, clips=clips, seed=np.int64(-1))
    la_sha = sha_file(lap)
    # the records
    cl = {"only_lead_gap_differs": True, "unchanged_off_the_named_rows": True, "equals_base_on_the_named_rows": True, "second_routine": True}
    jrec = {"pass_e0": fault != "e0_clause", "clauses": dict(cl, second_routine=fault != "e0_clause"), "counts": {"n_replaced_rows": 30, "n_label_rows": 32, "n_replaced_rows_above_gap_max": 1},
            "join": {"sha256": sha_file(jp) if fault != "e0" else "0" * 64}, "base": {"sha256": sha_file(gp)}, "eval_join_sha256": sha_file(ej)}
    jr = os.path.join(base, "JLE_RECORD.json")
    json.dump(jrec, io.open(jr, "w", encoding="utf-8"))
    gr = os.path.join(base, "GAPERR_GAPFILES_RECORD.json")
    json.dump({"la_file": {"sha256": la_sha if fault != "e7_lafile" else "1" * 64}}, io.open(gr, "w", encoding="utf-8"))
    wrap = WRAPPER_SHA + "0" * 48
    reader_gap = 20.0 + 0.2 * np.arange(n)
    clos = np.where(np.arange(n) % 2 == 0, 0.5, 0.0)
    ones = np.ones(n, bool)
    valid = (lv == 1) & np.isfinite(lg_jle) & (lg_jle >= 0.0) & (lg_jle <= GAP_MAX_M)
    for S in SETTINGS:
        for m in SEEDS:
            # the reference runs: RR (reader gap logged at every lead step; K0 line without optional fields), RLc (text only matters)
            _write_run(pull, run_name(S, "RR"), m, run_line(run_name(S, "RR"), S, m, "f" * 64, "RR", True), ci, fr, ones, reader_gap + 1e-5, clos, meta=False)
            _write_run(pull, run_name(S, "RLc"), m, run_line(run_name(S, "RLc"), S, m, "f" * 64, "RLc", True), ci, fr, valid, np.where(valid, lg_eval, np.nan), None, meta=False)
            # PL: the rule reads its lead from the planted join
            g_pl = np.where(valid, np.nan_to_num(lg_jle) + 1e-5, np.nan)
            pres_pl = valid.copy()
            if S == "K0" and m == 1:
                if fault == "e7":
                    g_pl[1] += 0.5
                if fault == "e7_present":
                    pres_pl[2] = True
                    g_pl[2] = 5.0
                if fault == "e7_missing":
                    pres_pl[4] = False
                if fault == "e7_above":
                    pres_pl[12 + 5] = True
                    g_pl[12 + 5] = 75.0
            first = run_line(run_name(S, "PL"), S, m, wrap if not (fault == "e1_run" and S == "K30" and m == 0) else "e" * 64, "RLc", False, " rule-join /w/JLE.npz rule join sha256 " + "ab" * 32)
            if fault == "e2" and S == "K0" and m == 0:
                first = first.replace("kappa 0.2", "kappa 0.3")
            if fault == "e2_default" and S == "K0" and m == 1:
                first = first.replace("preroll 0", "preroll 30")
            _write_run(pull, run_name(S, "PL"), m, first, ci, fr, pres_pl, g_pl, np.zeros(n), meta=False, done=not (fault == "e6_done" and S == "K30" and m == 0),
                       ndump=3 if not (fault == "e6" and S == "K0" and m == 0) else 2)
            if S == "K0":                                                              # LA at K0: the camera presence, the label gap file VGAPA_LA
                g = np.where(hasla, la_gap, reader_gap) + 1e-5
                if fault == "e7_la" and m == 1:
                    g[3] += 0.5
                c2 = np.zeros(n) if fault == "e7_closing" else clos
                first = run_line(run_name(S, "LA"), S, m, wrap, "RR", False, " vis-gap-file /w/VGAPA_LA.npz gap file sha256 %s vis-closing 1" % la_sha)
                _write_run(pull, run_name(S, "LA"), m, first, ci, fr, ones, g, c2, sha=la_sha if fault != "e7_sha" else "2" * 64)
    chk = os.path.join(base, "CHECK_WRAPPER_V_DONE.txt")
    io.open(chk, "w", encoding="utf-8").write("a\n" + (CHECK_LAST if fault != "e1" else "ZZ CHECK-WRAPPER-V FAIL") + "\n\n")
    hs = os.path.join(base, "CHECK_WRAPPER_V.hashes")
    io.open(hs, "w", encoding="utf-8").write("sha %s\n" % WRAPPER_SHA)
    tq, tr = os.path.join(base, "q_pytest.out"), os.path.join(base, "r_pytest.out")
    io.open(tq, "w", encoding="utf-8").write("....\n12 passed in 3.1s\n")
    io.open(tr, "w", encoding="utf-8").write("....\n== 30 passed, 2 warnings in 9.0s ==\n")

    class A:
        pass
    a = A()
    a.pull, a.grid_dir, a.grid_pinned, a.gap_file, a.gap_record, a.la_file = pull, gd, os.path.join(gd, PINNED_GRID_NAME), gp, gr, lap
    a.jle_file, a.jle_record, a.eval_join, a.expect_dumps = jp, jr, ej, 3
    a.wrapper_check, a.wrapper_hashes, a.tests_queue, a.tests_read = chk, hs, tq, tr
    a.tests_mtime_queue, a.tests_mtime_read, a.queue_start, a.controls_start, a.done_marker = 1000.0, 1010.0, 1100.0, 1200.0, ""
    if fault == "e4":
        a.tests_mtime_read = 1300.0
    lv_ = {S: {arm: dict(zip("CUF", v)) for arm, v in EXPECTED[S].items()} for S in SETTINGS}
    lv_["K0"]["LA"], lv_["K0"]["PL"], lv_["K30"]["PL"] = {"C": 0.0, "U": 0.1, "F": 0.2}, {"C": 0.0, "U": 0.1, "F": 0.2}, {"C": 0.0, "U": 0.1, "F": 0.2}
    if fault == "e3":
        lv_["K30"]["LA"]["U"] += 0.001
    st = {S: {"levels": lv_[S], "grid_all_pass": True, "strategic_a": True, "strategic_b": True} for S in SETTINGS}
    if fault == "e5":
        st["K30"]["strategic_b"] = False
    return a, {"settings": st}, WRAPPER_SHA


def mk_payload(ivs=None):
    """a synthetic payload for the names: ivs = {(setting, pair, measure): interval}; default 'zero' (not separated)"""
    z = [-0.01, 0.01]
    st = {}
    for S in SETTINGS:
        pr = {nm: {m: {"interval": list(z)} for m in "CUF"} for nm in PAIRS}
        for (s2, nm, m), iv in (ivs or {}).items():
            if s2 == S:
                pr[nm][m]["interval"] = list(iv)
        st[S] = {"levels": {arm: {"C": 0.0, "U": 0.1, "F": 0.5} for arm in ARMS}, "pairs": pr}
    return {"settings": st}


def selftest():
    ok = True
    bind(os.environ.get("PRESATTR_MODEL_READER", ""))
    with tempfile.TemporaryDirectory() as td:
        for fault in (None,) + CONTROLS:
            a, m, wsha = make_world(os.path.join(td, "w_%s" % fault), fault)
            c = compute_controls(a, m, wsha)
            flags = {k: v["pass"] for k, v in c.items()}
            want = {k: (k != fault) for k in CONTROLS}
            if flags != want:
                print("SELFTEST fault %s: flags %s" % (fault, flags))
                ok = False
    ok &= MD.WRAPPER_SHA == WRAPPER_SHA and MD.CHECK_LAST == CHECK_LAST
    hi = [0.01, 0.05]
    nm = all_names(mk_payload({("K0", "GEc-VS-PL", "U"): hi}))
    ok &= nm["K0_OVERALL"] == PRE + "-K0-PRESENCE-CARRIES-UNSAFE" and nm["K30_OVERALL"] == PRE + "-K30-UNSAFE-NOT-ATTRIBUTED"
    print("ZZ READ-PRESROLL10K SELFTEST %s" % ("OK" if ok else "FAIL"))
    return 0 if ok else 1


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    ap = argparse.ArgumentParser(allow_abbrev=False)
    ap.add_argument("--stage", choices=("controls", "names"))
    ap.add_argument("--selftest", action="store_true")
    for nme in ("pull", "code", "grid-dir", "grid-pinned", "w", "tree", "wrapper-file", "wrapper-check", "wrapper-hashes", "controls", "gap-file", "gap-record", "margin-dir", "margin-record", "wrapper-p-file", "wrapper-p-record", "wrapper-p-check", "pres-dir",
                "eval-join", "tests-queue", "tests-read", "tests-mtime-queue", "tests-mtime-read", "queue-start", "controls-start", "done-marker", "model-reader"):
        ap.add_argument("--" + nme, default="")
    ap.add_argument("--out", default="")
    ap.add_argument("--log", default="")
    ap.add_argument("--n-boot", type=int, default=2000)
    ap.add_argument("--expect-dumps", type=int, default=EXPECT_DUMPS)
    a = ap.parse_args(argv)
    if a.selftest:
        print("REFUSED: the selftest is tied to the world of the source readers and is not part of this kit")
        return 2
    if not a.stage or not a.out:
        print("REFUSED: --stage and --out are required")
        return 2
    bind(a.model_reader)
    a.n_boot_control = 300
    if os.path.exists(a.out):
        print("REFUSED: %s exists" % a.out)
        return 2
    if a.stage == "controls":
        a.gap_file = a.gap_file or WS + "/cropscale/gapfiles/VGAPLE.npz"
        a.gap_record = a.gap_record or WS + "/gaperr/gapfiles/GAPERR_GAPFILES_RECORD.json"
        a.margin_dir = a.margin_dir or WS + "/gapmargin/gapfiles"
        a.margin_record = a.margin_record or a.margin_dir + "/GAPMARGIN_GAPFILES_RECORD.json"
        a.wrapper_p_file = a.wrapper_p_file or WS + "/presroll/kit_wrap/v8f_t1_eval_reader_rule_rzgfhqetjvp.py"
        a.wrapper_p_record = a.wrapper_p_record or WS + "/presroll/kit_wrap/WRAPPER_P_GEN_RECORD.json"
        a.wrapper_p_check = a.wrapper_p_check or WS + "/presroll/check_p/CHECK_WRAPPER_P.out"
        a.pres_dir = a.pres_dir or WS + "/preshead2/dump"
        a.grid_pinned = a.grid_pinned or WS + "/hierrep/pins/" + PINNED_GRID_NAME
        a.tests_queue = a.tests_queue or WS + "/presroll/lead_tests/lead_pytest_queue.out"
        a.tests_read = a.tests_read or WS + "/presroll/lead_tests/lead_pytest_read.out"
        res = run_controls(a)
        io.open(a.out, "w", encoding="utf-8", newline="\n").write(json.dumps(res, indent=1, default=lambda o: float(o) if hasattr(o, "item") else str(o)))
        for k in CONTROLS:
            print("%s %s" % (k, "PASS" if (res["controls"].get(k) or {}).get("pass") else "FAIL"))
        print("ZZ READ-PRESROLL10K controls all_pass %s" % res["all_pass"])
        return 0
    cj = read_json(a.controls) or {}
    if cj.get("card") != CARD or cj.get("all_pass") is not True or "payload" not in cj or sorted(cj.get("controls", {})) != sorted(CONTROLS) \
            or any((v or {}).get("pass") is not True for v in cj.get("controls", {}).values()):
        print("REFUSED: the controls file is not all-pass with e0 to e8 present: no name is written")
        print("ZZ READ-PRESROLL10K names refused")
        return 3
    logp = a.log or (os.path.splitext(a.out)[0] + "_names.log")
    if os.path.exists(logp):
        print("REFUSED: %s exists" % logp)
        return 2
    names = all_names(cj["payload"])
    res = {"card": CARD, "tier": TIER, "controls_file": os.path.abspath(a.controls), "controls_sha256": sha_file(a.controls), "names": names, "values": cj["payload"]}
    io.open(a.out, "w", encoding="utf-8", newline="\n").write(json.dumps(res, indent=1))
    lines = print_sections(cj["payload"], names) + ["ZZ READ-PRESROLL10K names done"]
    io.open(logp, "w", encoding="utf-8", newline="\n").write("\n".join(lines) + "\n")
    for ln in lines:
        print(ln)
    return 0


try:
    bind(os.environ.get("PRESATTR_MODEL_READER", ""))
except ImportError as _ex:                      # bound again in main() from --model-reader; a missing one is reported there
    print("NOTE: %s" % _ex, file=sys.stderr)

if __name__ == "__main__":
    sys.exit(main())
